export function lowerBoundTrace(values,target){if(!Array.isArray(values)||!Number.isFinite(target)||values.some((v,i)=>!Number.isFinite(v)||(i>0&&v<values[i-1])))throw new TypeError('Sorted finite input required');let left=0,right=values.length;const frames=[{left,right,middle:null,message:`Initial interval [0,${right}); boundary may be ${right}, after the array.`}];while(left<right){const middle=left+Math.floor((right-left)/2),valid=values[middle]>=target;if(valid)right=middle;else left=middle+1;frames.push({left,right,middle,valid,message:`Probe index ${middle}: ${values[middle]} ≥ ${target} is ${valid}. ${valid?'Keep this possible first valid position; right=middle.':'This and every earlier position are too small; left=middle+1.'}`});}frames.push({left,right,middle:null,message:`Stop: left=right=${left}. ${left===values.length?'No array position satisfies the predicate.':'This is the first position with value at least target.'}`});return frames;}
export function reverseTrace(values){if(!Array.isArray(values)||values.some(v=>!Number.isFinite(v)))throw new TypeError('Finite values required');const links=values.map((_,i)=>i+1<values.length?i+1:null),frames=[];let previous=null,current=values.length?0:null,saved=null;const snapshot=(phase,message)=>frames.push({phase,message,previous,current,saved,links:[...links]});snapshot('start','Previous is null; current is the original head.');while(current!==null){saved=links[current];snapshot('saved',`Save node ${current}'s old next (${saved===null?'null':saved}) before changing its link.`);links[current]=previous;snapshot('rewired',`Change node ${current}.next to ${previous===null?'null':previous}. Saved next still reaches the unprocessed suffix.`);previous=current;current=saved;saved=null;snapshot('advanced','Advance previous and current. The reversed prefix and forward suffix remain disjoint.');}snapshot('done',`Current is null; return previous ${previous===null?'null':previous} as the new head.`);return frames;}
export function exactSearchTrace(values,target){
  if(!Array.isArray(values)||!Number.isFinite(target)||values.some((v,i)=>!Number.isFinite(v)||(i>0&&v<values[i-1])))throw new TypeError('Sorted finite input required');
  let left=0,right=values.length-1;
  const frames=[{left,right,middle:null,nextLeft:left,nextRight:right,result:null,message:`Initial closed interval [${left},${right}].`}];
  while(left<=right){
    const middle=left+Math.floor((right-left)/2),oldLeft=left,oldRight=right;
    if(values[middle]===target){frames.push({left,right,middle,nextLeft:left,nextRight:right,result:middle,message:`Probe index ${middle}: ${target} equals ${values[middle]}. Return index ${middle}.`});return frames;}
    if(values[middle]<target)left=middle+1;else right=middle-1;
    frames.push({left:oldLeft,right:oldRight,middle,nextLeft:left,nextRight:right,result:null,message:`Probe index ${middle}: ${values[middle]} ${values[middle]<target?'is below':'is above'} ${target}. Next interval [${left},${right}].`});
  }
  frames.push({left,right,middle:null,nextLeft:left,nextRight:right,result:-1,message:'The closed interval is empty. Return −1: no exact match.'});
  return frames;
}
